# POST /api/sheets/{sheetId}/people/{personId}/transfer — transfer a person to another sheet by id (body:
# {to, user}). Only a steward transfers. The person arrives on the other sheet with every grade (and its
# from-date), their terms, contact and aliases, and their claims with their status, dates, notes, frozen
# figures, logs and comments; each claim that had a number takes the other sheet's next number, in the order
# the claims were opened (by the sheet's today when each was opened, then the order they were added). Figures a
# statement bound are lost, the statement count starts at 0 and references are not carried. They leave this
# sheet entirely (patron links, pool memberships, holds, statements and watches dropped). Refused (400),
# storing nothing, when the user is not a steward, the person is not on the sheet or is retired, the other
# sheet is missing, this sheet or archived, or already has their name, an alias of theirs or their contact.
# A stored transfer is recorded as PERSON_TRANSFERRED on both sheets, each followed by its rollup lines.
validate:
  class: net.officefloor.hq.app.person.ValidateTransfer
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: snapshot
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: transfer
transfer:
  class: net.officefloor.hq.app.person.TransferPerson
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.person.AuditPersonTransferred
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithTransferred
  govern: [ transaction ]
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimLogStore;
import net.officefloor.hq.app.claim.ClaimStore;
import net.officefloor.hq.app.claim.Numbering;
import net.officefloor.hq.app.period.PeriodStore;
import net.officefloor.hq.app.pool.PoolStore;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Transfers the person to another sheet, refusing a retired person, an archived sheet, or a name, alias or
 *  contact of theirs already on it (a name or alias also when on another sheet of its tree). They arrive with their grades, terms, contact, aliases and claims; each claim
 *  that had a number takes the other sheet's next, in the order they were opened (by the sheet's today when each
 *  was opened, then the order they were added). They leave this sheet entirely. */
public class TransferPerson {
    public void transfer(@Val TransferRequest request, @Val Person person, PersonStore people, ClaimStore claims,
            ClaimLogStore log, PatronStore patrons, PoolStore pools, SheetStore sheets, SettingStore settings,
            PeriodStore periods, RollupService rollups, Out<Transferred> transferred) throws InvalidSheetException {
        String from = person.getSheetId();
        String to = request.to();
        if (person.isRetired()) {
            throw new InvalidSheetException("A retired person cannot be transferred");
        }
        sheets.refuseArchived(to);
        // the sheet they leave is not counted: they take their names with them
        List<String> tree = settings.tree(to).stream().filter(s -> !s.equals(from)).toList();
        if (people.nameTaken(to, person.getName(), null) || people.usedOn(tree, person.getName())) {
            throw new InvalidSheetException("The other sheet already has " + person.getName());
        }
        for (String alias : person.getAliases()) {
            if (people.nameTaken(to, alias, null) || people.usedOn(tree, alias)) {
                throw new InvalidSheetException("The other sheet already has " + alias);
            }
        }
        if (person.getContact() != null && people.contactTaken(to, person.getContact(), null)) {
            throw new InvalidSheetException("The other sheet already has the contact " + person.getContact());
        }

        Map<Long, LocalDate> opened = log.openedOn(from);
        List<Claim> theirs = new ArrayList<>(claims.list(from).stream()
                .filter(c -> c.getPersonId() == person.getId()).toList());
        List<Claim> numbered = new ArrayList<>(theirs.stream().filter(c -> c.getNumber() != null).toList());
        numbered.sort(Comparator.comparing((Claim c) -> opened.getOrDefault(c.getId(), c.getDate()))
                .thenComparingLong(Claim::getId));

        var before = rollups.snapshot(to);
        sheets.markLoaded(to);
        Map<String, String> numbers = new HashMap<>();
        Map<Long, String> numberOf = new HashMap<>();
        for (Claim claim : numbered) {
            String number = Numbering.next(to, claim.getDueBy(), claims, settings, sheets, periods);
            numbers.putIfAbsent(claim.getNumber(), number);
            numberOf.put(claim.getId(), number);
        }
        Person copy = people.copyTo(person, to);
        // listed newest first: copy the oldest first, so they keep their order
        for (int i = theirs.size() - 1; i >= 0; i--) {
            Claim claim = theirs.get(i);
            claims.copyTo(claim, to, copy.getId(), numberOf.get(claim.getId()), renumbered(claim.getCorrects(), numbers),
                    renumbered(claim.getSplitFrom(), numbers));
        }

        claims.removeAll(from, person.getId());
        patrons.drop(from, person.getId());
        pools.drop(from, person.getId());
        people.remove(person);
        transferred.set(new Transferred(to, copy, before));
    }

    /** The number a claim's number became on the other sheet; as it was when that claim did not go with it. */
    private static String renumbered(String number, Map<String, String> numbers) {
        return number == null ? null : numbers.getOrDefault(number, number);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.plugin.variable.Val;

/** Records a transfer on both sheets: PERSON_TRANSFERRED sheet=<this> by=<user> name=<name> to=<other>, then
 *  PERSON_TRANSFERRED sheet=<other> by=<user> name=<name> from=<this>, each followed by how it moved that
 *  sheet's figures. */
public class AuditPersonTransferred {
    public void audit(@Val TransferRequest request, @Val Person person, @Val Transferred transferred,
            @Val Rollup before, Audit audit, RollupService rollups) {
        String from = person.getSheetId();
        String to = transferred.to();
        audit.record("PERSON_TRANSFERRED sheet=" + from + " by=" + request.user() + " name=" + person.getName()
                + " to=" + to);
        rollups.record(from, request.user(), before);
        audit.record("PERSON_TRANSFERRED sheet=" + to + " by=" + request.user() + " name=" + person.getName()
                + " from=" + from);
        rollups.record(to, request.user(), transferred.toBefore());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.rollup.Rollup;

/** A person transferred: the sheet they went to, their copy there, and that sheet's figures before they arrived. */
public record Transferred(String to, Person person, Rollup toBefore) {
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Refuses a transfer by anyone but a steward, or to no sheet or this sheet itself. */
public class ValidateTransfer {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody TransferRequest request, RoleStore roles,
            Out<TransferRequest> body) throws InvalidSheetException {
        String user = request == null || request.user() == null ? "" : request.user().trim();
        roles.refuseChange(sheetId.trim(), user);
        if (roles.find(sheetId.trim(), user) != Role.STEWARD) {
            throw new InvalidSheetException("Only a steward may transfer people");
        }
        String to = request.to() == null ? "" : request.to().trim();
        if (to.isEmpty()) {
            throw new InvalidSheetException("Give the id of the sheet to transfer to");
        }
        if (to.equals(sheetId.trim())) {
            throw new InvalidSheetException("A person cannot be transferred to their own sheet");
        }
        body.set(new TransferRequest(to, user));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

/** Responds with where the person went: the other sheet and their id there. */
public class RespondWithTransferred {
    public void respond(@Val Transferred transferred, ObjectResponse<TransferResponse> response) {
        response.send(new TransferResponse(transferred.to(), transferred.person().getId()));
    }
}
package net.officefloor.hq.app.person;

/** The answer to a transfer: the sheet the person went to and their id there. */
public record TransferResponse(String to, long id) {
}

